INSERT INTO news (title_es, title_en, title_fr, description_es, description_en, description_fr, image_url, date, link_url, media_type, is_published)
VALUES
('LA PROVINCIA', 'LA PROVINCIA', 'LA PROVINCIA', 'En el marco del Día Internacional de la Mujer y la Niña en la Ciencia, llega por primera vez a Canarias la exposición Mujeres Nobel, que da a conocer a las mujeres que han sido galardonadas con el Premio Nobel en sus cinco disciplinas, Literatura, Paz, Física, Química y Medicina.', 'Within the framework of the International Day of Women and Girls in Science, the Nobel Women exhibition arrives for the first time in the Canary Islands, which makes known the women who have been awarded the Nobel Prize in its five disciplines, Literature, Peace , Physics, Chemistry and Medicine.', 'Dans le cadre de la Journée internationale des femmes et des filles de science, l''exposition Nobel Women arrive pour la première fois aux Canaries, qui fait connaître les femmes qui ont reçu le prix Nobel dans ses cinq disciplines, Littérature, Paix , Physique, chimie et médecine.', 'https://xwol5lxaqceczvs1.public.blob.vercel-storage.com/rocaviva/communication/1.jpg', '2020-02-15', 'https://ocio.laprovincia.es/agenda/noticias/nws-782699-exposicion-mujeres-nobel.html', 'press', true),
('TELDE ACTUALIDAD', 'TELDE ACTUALIDAD', 'TELDE ACTUALIDAD', 'El Servicio de Museos del Cabildo de Gran Canaria organiza junto a Rocaviva Eventos esta exposición que ya han visto más de 500.000 personas tanto en el territorio nacional como internacional, y que ahora puede disfrutarse en tres espacios de su red museística: Casa de Colón (categoría de Ciencias), Casa-Museo Pérez Galdós (categoría Literatura) y Casa-Museo León y Castillo de Telde (categoría Paz).', 'With Rocaviva Eventos, the Museum Service of the Cabildo de Gran Canaria organizes this exhibition that has already been seen by more than 500,000 people both in national and international territory, and which can now be enjoyed in three spaces of its museum network: Casa de Colón (category of Sciences), Pérez Galdós House-Museum (Literature category) and León and Castillo de Telde House-Museum (Peace category).', 'En collaboration avec Rocaviva Eventos, le Service des musées du Cabildo de Gran Canaria organise cette exposition qui a déjà été vue par plus de 500000 personnes sur le territoire national et international, et qui peut désormais être appréciée dans trois espaces de son réseau muséal: Casa de Colón (catégorie des sciences), Maison-musée Pérez Galdós (catégorie Littérature) et Maison-musée León et Castillo de Telde (catégorie Paix).', 'https://xwol5lxaqceczvs1.public.blob.vercel-storage.com/rocaviva/communication/2.jpg', '2020-02-15', 'https://www.teldeactualidad.com/hemeroteca/noticia/cultura/2020/02/12/8030.html', 'press', true),
('CASA MUSEO PEREZ GALDÓS', 'CASA MUSEO PEREZ GALDÓS', 'CASA MUSEO PEREZ GALDÓS', 'La muestra organizada por el Servicio de Museos de la Consejería de Cultura del Cabildo grancanario junto a Rocaviva Eventos, es la primera vez que se expone en la isla, dando a conocer el relevante papel de las 53 mujeres que han obtenido el prestigioso Nobel en alguna de sus categorías.', 'The exhibition organized by the Museum Service of the Ministry of Culture of the Cabildo Gran Canaria together with Rocaviva Eventos, is the first time that it has been exhibited on the island, revealing the relevant role of the 53 women who have obtained the prestigious Nobel in some of their categories.', 'L''exposition organisée par le Service des musées du Conseil de la culture du Cabildo Gran Canaria avec Rocaviva Eventos, est la première fois qu''elle est exposée sur l''île, révélant le rôle pertinent des 53 femmes qui ont obtenu le prestigieux Nobel dans certains de leurs catégories.', 'https://xwol5lxaqceczvs1.public.blob.vercel-storage.com/rocaviva/communication/3.jpg', '2020-02-12', 'http://www.casamuseoperezgaldos.com/noticias/-/asset_publisher/SLIvsEZ3Eiul/content/noticia-cada-persona-puede-alcanzar-la-excelencia-/7531811', 'press', true),
('RADIO FARO DEL NOROESTE', 'RADIO FARO DEL NOROESTE', 'RADIO FARO DEL NOROESTE', 'Entrevista a las comisarias de la exposición: ''Mujeres Nobel''. A Belén Yuste y a Sonnia Rivas Caballero les une la pasión por dar a conocer la vida y la obra de personajes históricos. Ahora, llegan a Gran Canaria con la exposición ‘Mujeres Nobel’ que impulsa la Consejería de Cultura del Cabildo de Gran Canaria, cuyo objetivo fundamental es poner en valor a aquellas mujeres galardonadas con el premio Nobel y que tienen en común una vida al servicio de la Humanidad.', 'Interview with the curators of the exhibition: ''Nobel Women''. Belén Yuste and Sonnia Rivas Caballero are united by a passion for making the life and work of historical figures known. Now, they arrive in Gran Canaria with the exhibition ''Nobel Women'' promoted by the Ministry of Culture of the Cabildo de Gran Canaria, whose fundamental objective is to value those women awarded the Nobel Prize and who have in common a life in the service of The humanity.', 'Entretien avec les commissaires de l''exposition: ''Nobel Women''. Belén Yuste et Sonnia Rivas Caballero sont unis par la passion de faire connaître la vie et l''œuvre de personnages historiques. Maintenant, ils arrivent à Gran Canaria avec l''exposition `` Nobel Women '''' promue par le ministère de la Culture du Cabildo de Gran Canaria, dont l''objectif fondamental est de valoriser les femmes qui ont reçu le prix Nobel et qui ont en commun une vie au service de l''humanité.', 'https://xwol5lxaqceczvs1.public.blob.vercel-storage.com/rocaviva/communication/4.jpg', '2020-02-12', 'http://www.radiofarodelnoroeste.es/online/index.php/2016-09-27-10-08-34/item/29752-entrevista-a-las-comisarias-de-la-exposicion-mujeres-nobel', 'press', true),
('ABC', 'ABC', 'ABC', '«Mujeres Nobel» en Sevilla. Además de los paneles explicativos monográficos sobre cada una de las mencionadas mujeres que a lo largo de la historia han recibido este prestigioso galardón, la muestra incluye también varios paneles que a manera de píldoras recuerdan los principales rasgos de la obra de algunas de las mujeres galardonas con los Premios Nobel de Literatura y de La Paz.', '''Nobel Women'' in Seville. In addition to the monographic explanatory panels on each of the aforementioned women who throughout history have received this prestigious award, the sample also includes several panels that, like pills, recall the main features of the work of some of the award-winning women with the Nobel Prize for Literature and La Paz.', '«Femmes Nobel» a Seville. Outre les panneaux explicatifs monographiques sur chacune des femmes susmentionnées qui à travers l''histoire ont reçu ce prix prestigieux, l''exposition comprend également plusieurs panneaux qui, comme des pilules, rappellent les principales caractéristiques du travail de certaines des femmes lauréates. avec le prix Nobel de littérature et La Paz.', 'https://xwol5lxaqceczvs1.public.blob.vercel-storage.com/rocaviva/communication/5.jpg', '2020-02-12', 'https://sevilla.abc.es/sevilla/sevi-mujeres-nobel-sevilla-40247647543-20200212083921_galeria.html#imagen1', 'press', true),
